import torch, torch.nn as nn
class ToM(nn.Module):
    def __init__(self, d_in, d_h=64):
        super().__init__()
        self.rnn = nn.GRU(d_in, d_h, batch_first=True)
        self.head1, self.head2 = nn.Linear(d_h, d_h), nn.Linear(d_h, d_h)
    def forward(self, hist):          # hist: [B,T,d_in]
        h, _ = self.rnn(hist)
        return self.head1(h[:, -1]), self.head2(h[:, -1])

import torch, torch.nn as nn
class Reward(nn.Module):
    def __init__(self, d_s, d_a, d_b):
        super().__init__()
        self.net = nn.Sequential(nn.Linear(d_s+d_a+d_b,128), nn.ReLU(), nn.Linear(128,1))
    def forward(self, s, a, b_hat):
        return self.net(torch.cat([s, a, b_hat], dim=-1))

import torch.nn.functional as F
def loss_tok(logits, tokens):        # logits:[B,H,V]
    return F.cross_entropy(logits.reshape(-1, logits.size(-1)), tokens.reshape(-1))
def loss_cont(pred, target):
    return F.mse_loss(pred, target)

def recast_loop(router, compiler, answer, q, max_steps=6):
    h = []
    for k in range(max_steps):
        c = router.propose(q, h)           # 选操作
        if c is None:                      # 判定证据充分
            break
        h.append(exec(compiler.compile(c)))
    return answer.solve(q, h)

import torch
def residual(X, T, xi, uv, project):
    pred = project(X, T, xi)             # [N,2]
    return (pred - uv).norm(dim=-1)
def robust_cost(r, delta=1.0):
    return torch.where(r.abs() < delta, 0.5*r**2, delta*(r.abs()-0.5*delta)).sum()
